"""Build dependency-free, semantic portfolio pages from content/site.json."""
from pathlib import Path
import json, html
ROOT = Path(__file__).parent
D = json.loads((ROOT/'content/site.json').read_text())
OUT = ROOT/'dist'
def e(s): return html.escape(str(s), quote=True)
def enquiry(service='',kind='paid'): return '/contact/?service='+service+'&type='+kind+'#enquiry'
def button(text,url,outline=False): return f'<a class="btn{ " outline" if outline else ""}" href="{e(url)}">{e(text)} <span aria-hidden="true">→</span></a>'
def heading(label,title,desc=''): return f'<div class="section-heading"><div><div class="eyebrow">{label}</div><h2>{title}</h2></div>{"<p>"+desc+"</p>" if desc else ""}</div>'
def download(key):
    item=D['downloads'][key]
    if not item.get("public_approved", False): return '<p class="small">Source document reviewed privately. Download withheld pending sharing approval.</p>'
    return f'<a class="btn outline" href="{e(item["path"])}" download>{e(item["label"])} <span aria-hidden="true">↓ PDF</span></a>'
def section(id,body,cls=''): return f'<section id="{id}" class="{cls}"><div class="wrap">{body}</div></section>'
def nav(active):
    links=''.join(f'<a href="{url}"'+(' aria-current="page"' if label==active else '')+f'>{label}</a>' for label,url in [('Home','/'),('Services','/services/'),('Selected Work','/#work'),('About','/about/'),('Contact','/contact/')])
    return f'<a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap nav"><a class="brand" href="/" aria-label="Asif Hussain home"><span class="monogram" aria-hidden="true">AH</span><span><strong>{e(D["name"])}</strong><small>Economic research & data analysis</small></span></a><button class="menu" type="button" aria-controls="navlinks" aria-expanded="false">Menu</button><nav id="navlinks" class="navlinks" aria-label="Main navigation">{links}{button("Request a Free Trial",enquiry(kind="trial"))}</nav></div></header>'
def write(path,title,desc,body,active=''):
    folder=OUT/path; folder.mkdir(parents=True,exist_ok=True)
    footer=f'<footer class="footer"><div class="wrap footer-inner"><span>© {e(D["name"])} · Economic Research & Data Analyst</span><span>Pakistan · Remote collaboration · <a href="{e(D["linkedin"])}" target="_blank" rel="noopener noreferrer">LinkedIn →</a></span><a href="/contact/">Let’s discuss your project</a></div></footer>'
    document=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} | Asif Hussain</title><meta name="description" content="{e(desc)}"><meta name="theme-color" content="#142d40"><meta name="robots" content="noindex,nofollow"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script></head><body>{nav(active)}<main id="main">{body}</main>{footer}</body></html>'
    (folder/'index.html').write_text(document)
def hero():
    art='''<div class="hero-art" role="img" aria-label="Decorative analytical illustration: an abstract curve and research workflow, not measured data"><div class="art-top"><span>Research → Clarity</span><span>AH / 01</span></div><svg viewBox="0 0 400 290" aria-hidden="true"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M 40 0 L 0 0 0 40" fill="none" stroke="#cbd5cb" stroke-width=".7"/></pattern></defs><rect x="0" y="0" width="400" height="260" fill="url(#grid)"/><path d="M15 218 C65 218 75 199 112 180 S172 198 210 142 S265 132 290 89 S345 86 385 36" fill="none" stroke="#236b66" stroke-width="2.5"/><path d="M15 230 C72 199 114 235 159 164 S213 193 255 141 S330 139 385 93" fill="none" stroke="#839b95" stroke-dasharray="4 6"/><circle cx="210" cy="142" r="6" fill="#142d40"/><path d="M210 142 V65 H300" stroke="#142d40" fill="none" stroke-width=".8"/><rect x="215" y="34" width="139" height="31" fill="#142d40"/><text x="229" y="54" font-family="sans-serif" font-size="10" fill="#fffefa">Evidence → insight</text><text x="0" y="286" font-family="sans-serif" font-size="9" fill="#59686e">QUESTION</text><text x="337" y="286" font-family="sans-serif" font-size="9" fill="#59686e">INSIGHT</text></svg><div class="art-bottom"><span><strong>01</strong>Define the question</span><span><strong>02</strong>Examine the evidence</span><span><strong>03</strong>Explain clearly</span></div><p class="art-caption">Decorative analytical composition · No measured data or research findings</p></div>'''
    return f'<div class="hero"><div class="wrap"><div class="hero-grid"><div><div class="eyebrow">Asif Hussain · Economic Research & Data Analyst</div><h1>Clear Research.<br>Reliable Analysis.<br><em>Better-Informed<br>Decisions.</em></h1><p class="intro">{e(D["introduction"])}</p><div class="actions">{button("Request a Free Trial",enquiry(kind="trial"))}{button("Explore My Work","#work",True)}</div><p class="remote"><span class="dot"></span>Based in Pakistan · Working remotely with international clients</p></div>{art}</div><div class="hero-strip"><span>Economic & policy research</span><span>Statistical interpretation</span><span>Data preparation</span><span>Clear reporting</span></div></div></div>'
def services(full=False):
    body=heading('01 / Expertise','Research rigour.<br>Practical analytical support.','From a focused question to a clear deliverable. Services are scoped to your evidence, audience and needs.')
    for i,s in enumerate(D['services'],1):
        if full:
            body+=f'<article class="service-detail" id="{s["id"]}"><div><div class="eyebrow">Service {i:02}</div><h3>{e(s["name"])}</h3><p>{e(s["summary"])}</p>{button("Enquire about this service",enquiry(s["id"]))}</div><div><ul>'+''.join(f'<li>{e(a)}</li>' for a in s['activities'])+f'</ul><p><strong>Possible deliverables</strong><br>{e(s["deliverables"])}</p></div></article>'
        else:
            body+=f'<article class="service-row"><span class="number">{i:02}</span><div><h3><a href="/services/#{s["id"]}">{e(s["name"])}</a></h3><p>{e(s["summary"])}</p></div><p>{e(s["deliverables"])}</p><a class="text-link" href="{e(enquiry(s["id"]))}">Discuss a task →</a></article>'
    return section('services',body)
def projects():
    cards=[('south-asia','Descriptive public-data demonstration','Economic growth & women’s employment in South Asia','A comparison of Pakistan, Bangladesh and India using World Bank indicators, 2010–2024.'),('health-statistics','Revised statistical analysis sample','Statistical interpretation of a health dataset','An evidence-aware approach to summaries, group comparisons and statistical associations.'),('retail-analysis','Revised business analysis sample','Retail sales & profitability analysis','A clear reading of supplied sales, profit and distribution summaries across 51,290 records.')]
    visuals=[''.join(f'<div class="mini-row"><span>{r["country"][:3].upper()}</span><span class="mini-bar" style="width:{r["growth"]/110*100:.1f}%"></span></div>' for r in D['south_asia'])+'<span class="mini-note">Real GDP per capita growth · 2010–2024</span>', '<div style="font:32px Georgia;color:#142d40">Reading the<br>statistical evidence.</div><span class="mini-note">Methods · Interpretation · Limitations</span>', '<div class="mini-kpi">51,290<small>RECORDS IN SUPPLIED OUTPUTS</small></div><span class="mini-note">Sales · Profit · Distribution</span>']
    body=heading('02 / Selected work','Evidence you can explore.','Three analytical examples, with their sources, methods and limitations made explicit.')+'<div class="projects">'
    for (slug,label,title,desc),v in zip(cards,visuals):
        body+=f'<article class="project"><a class="project-visual" href="/work/{slug}/" aria-label="Read {e(title)}">{v}</a><div class="tag">{label}</div><h3>{title}</h3><p>{desc}</p><a class="text-link" href="/work/{slug}/">Explore case study →</a></article>'
    body+='</div><div class="highlights"><div><h3>MPhil research</h3><p>E-commerce, employment and inclusive growth across 20 developing countries, 2014–2023. Panel-data analytical methods.</p></div><div><h3>Ongoing research collaboration</h3><p>Inclusive Growth Index development and investigation of its determinants with Dr Dragana Radicic, University of Lincoln. Research collaboration; no institutional endorsement is implied.</p></div></div>'
    return section('work',body)
def workflow():
    return section('approach',heading('03 / Research approach','A clear process.<br>A considered result.')+'<div class="workflow">'+''.join(f'<article><span class="number">{i:02}</span><h3>{e(t)}</h3><p>{e(p)}</p></article>' for i,(t,p) in enumerate(D['workflow'],1))+'</div>')
def trial():
    body='<div class="trial-grid"><div><div class="eyebrow">04 / A small first step</div><h2>Start Small.<br>Evaluate the Work.<br>Collaborate with Confidence.</h2><p>Before committing to a larger project, we can agree on one small research or analysis task. This gives you an opportunity to evaluate the clarity, relevance, and quality of the deliverable.</p>'+button('Request My Free Trial',enquiry(kind='trial'))+'</div><div><ul class="conditions">'+''.join(f'<li>{e(c)}</li>' for c in D['trial_conditions'])+'</ul><p class="trial-tasks"><strong>Possible trial tasks</strong><br>'+' · '.join(e(t) for t in D['trial_tasks'])+'</p><p class="small">The trial scope and delivery date must be agreed before work starts. Full research assignments, advanced modelling, large dataset preparation, reports and ongoing consultancy are paid engagements.</p></div></div>'
    return section('trial',body,'trial')
def paid():
    body=heading('05 / Working together','Flexible ways to collaborate.','An agreed scope, transparent expectations and outputs suited to your project.')+'<div class="formats">'
    for t,p in [('Fixed-Scope Projects','Clearly defined research, analytical or reporting assignments with agreed deliverables and fees.'),('Hourly Research Support','Focused analytical assistance, ongoing tasks and time-based requirements.'),('Ongoing Collaboration','Recurring research and reporting support for organisations and consultants.')]: body+=f'<article class="format"><h3>{t}</h3><p>{p}</p><a class="text-link" href="{e(enquiry())}">Request a Quote →</a></article>'
    body+='</div><p class="small" style="margin-top:28px">Before work begins, we agree on deliverables, source materials, timelines, payment terms, revisions, confidentiality and communication expectations.</p><div class="journey">Initial Enquiry → Scope Discussion → Proposal or Agreed Pilot → Written Agreement → Delivery and Review</div>'
    return section('collaboration',body)
def about():
    events=[('2017–2021','BS Economics','University of Sargodha'),('2022–Present','Research Associate','ZAR Management Consultancies · Remote research assistance, data preparation, indicator analysis, quantitative support, statistical tables and charts, reporting and dashboard outputs.'),('2022–2024','MPhil Economics','Bahauddin Zakariya University, Multan · E-commerce, employment and inclusive growth in developing countries.'),('Ongoing research collaboration','Inclusive Growth Index development','Research collaboration with Dr Dragana Radicic, University of Lincoln, concerning index development and its determinants.')]
    body='<div class="about-grid"><div><div class="eyebrow">06 / Professional background</div><h2>Economics at the core.<br>Clarity in the output.</h2><p>'+e(D['bio'])+'</p><div class="tools"><strong>Core tools</strong><br>'+' · '.join(D['core_tools'])+'<br><br><strong>Working knowledge</strong><br>'+' · '.join(D['working_tools'])+'</div><div class="actions">'+download('cv')+'</div><p class="small">Supplied academic CV · PDF</p></div><div class="timeline">'+''.join(f'<article><small>{e(date)}</small><h3>{e(title)}</h3><p>{e(desc)}</p></article>' for date,title,desc in events)+'<p class="small">Education and employment periods overlap. Research collaboration is distinct from employment or institutional sponsorship.</p></div></div>'
    return section('about',body)
def faq():
    body='<div class="faq-layout"><div><div class="eyebrow">07 / Questions, answered</div><h2>Before we<br>begin.</h2><p class="small">A few practical details about research support, deliverables and working together.</p></div><div>'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in D['faq'])+'</div></div>'
    return section('faq',body)
def contact():
    opts='<option value="">Choose a service</option>'+''.join(f'<option value="{s["id"]}">{e(s["name"])}</option>' for s in D['services'])+'<option value="discuss">I would like to discuss the best fit</option>'
    body=f'''<div class="contact-grid"><div class="contact-copy"><div class="eyebrow">08 / Get in touch</div><h2>Have a Research or Data Challenge?<br>Let’s Discuss It.</h2><p>Tell me about your question, available evidence and intended outcome. We can then discuss a suitable scope.</p><p><strong>Email</strong><br><a href="mailto:{e(D['email'])}">{e(D['email'])}</a></p><p><strong>Professional profile</strong><br><a href="{e(D['linkedin'])}" target="_blank" rel="noopener noreferrer">Connect on LinkedIn →</a></p><p>Based in Pakistan<br>Remote collaboration with international clients</p></div><div><div class="fallback"><strong>Email-based enquiry</strong><br>This form prepares an email draft for your email app. It does not send or store your enquiry. Review the draft and send it yourself. If no email app is configured, copy the prepared message into your webmail.</div><form id="enquiry" novalidate data-email="{e(D['email'])}"><div class="form-grid"><div class="field"><label for="name">Full name *</label><input id="name" name="name" autocomplete="name" maxlength="120" required><span class="field-error" id="name-error"></span></div><div class="field"><label for="email">Email address *</label><input id="email" name="email" type="email" autocomplete="email" maxlength="254" required><span class="field-error" id="email-error"></span></div><div class="field full"><label for="organisation">Organisation or website <span class="small">(optional)</span></label><input id="organisation" name="organisation" autocomplete="organization" maxlength="250"></div><div class="field"><label for="service">Service required *</label><select id="service" name="service" required>{opts}</select><span class="field-error" id="service-error"></span></div><div class="field"><label for="type">Enquiry type *</label><select id="type" name="type"><option value="paid">Paid project</option><option value="trial">Free trial</option></select></div><div class="field full"><label for="description">Project description *</label><textarea id="description" name="description" maxlength="2000" required aria-describedby="description-hint description-error"></textarea><span id="description-hint" class="small">Describe your objective and intended output. Maximum 2,000 characters.</span><span class="field-error" id="description-error"></span></div><div class="field"><label for="deadline">Preferred deadline <span class="small">(optional)</span></label><input id="deadline" name="deadline" type="date"></div><div class="field" id="budget-field"><label for="budget">Budget range <span class="small">(optional)</span></label><input id="budget" name="budget" maxlength="120" placeholder="Your range and currency"></div></div><p class="privacy">Please do not upload confidential or sensitive datasets through this initial enquiry form. Secure data-sharing arrangements can be discussed separately.</p><button class="btn" id="prepare" type="submit">Prepare Email Enquiry <span aria-hidden="true">→</span></button><div class="form-status" id="form-status" role="status" aria-live="polite"></div><noscript><p>Form preparation requires JavaScript. Please email <a href="mailto:{e(D['email'])}">{e(D['email'])}</a> directly with your name, service required and project description.</p></noscript></form></div></div>'''
    return section('contact',body)
def page_hero(label,title,desc,meta=[]):
    return '<div class="page-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Home</a> / '+label+'</div><div class="eyebrow">'+label+'</div><h1>'+title+'</h1><p>'+desc+'</p>'+ ('<div class="meta-grid">'+''.join(f'<div><small>{e(k)}</small><p>{e(v)}</p></div>' for k,v in meta)+'</div>' if meta else '')+'</div></div>'
def svg_chart(title,desc,inner): return f'<svg viewBox="0 0 650 240" role="img" aria-label="{e(title)}"><title>{e(title)}</title><desc>{e(desc)}</desc>{inner}</svg>'
def south_charts():
    rows=D['south_asia']; bars=''
    for i,r in enumerate(rows):
        y=40+i*58; w=r['growth']/110*395
        bars+=f'<text x="0" y="{y+16}" font-size="13">{r["country"]}</text><rect x="116" y="{y}" width="{w:.2f}" height="26" fill="#236b66"><title>{r["country"]}: {r["growth"]:.2f}%</title></rect><text x="{126+w:.2f}" y="{y+17}" font-size="12">{r["growth"]:.2f}%</text>'
    bars+='<line x1="116" y1="210" x2="511" y2="210" stroke="#b9c6bf"/>'
    for n in [0,25,50,75,100]: bars+=f'<text x="{116+n/110*395}" y="231" text-anchor="middle" font-size="10">{n}%</text>'
    chart1='<figure class="chart-panel"><h3>Real GDP per capita growth</h3>'+svg_chart('GDP per capita growth, 2010–2024','Pakistan 30.11%; Bangladesh 105.72%; India 91.62%. Growth in GDP per capita measured in constant 2015 US dollars.',bars)+'<figcaption>Units: percentage change, 2010–2024. Underlying indicator: GDP per capita, constant 2015 US dollars. Source: World Bank World Development Indicators; endpoint summaries supplied by Asif Hussain.</figcaption></figure>'
    inner='<circle cx="124" cy="13" r="5" fill="#fffefa" stroke="#236b66" stroke-width="2"/><text x="137" y="17" font-size="11">2010</text><circle cx="219" cy="13" r="5" fill="#142d40"/><text x="232" y="17" font-size="11">2024</text>'
    for i,r in enumerate(rows):
        y=64+i*55; a=130+(r['employment_2010']-20)/20*400; b=130+(r['employment_2024']-20)/20*400
        inner+=f'<text x="0" y="{y+5}" font-size="13">{r["country"]}</text><line x1="{a}" y1="{y}" x2="{b}" y2="{y}" stroke="#236b66" stroke-width="3"/><circle cx="{a}" cy="{y}" r="5" fill="#fffefa" stroke="#236b66" stroke-width="2"/><circle cx="{b}" cy="{y}" r="5" fill="#142d40"/><text x="{a-8}" y="{y-12}" font-size="10" text-anchor="end">{r["employment_2010"]:.3f}%</text><text x="{b+8}" y="{y+19}" font-size="10">{r["employment_2024"]:.3f}%</text>'
    inner+='<line x1="130" y1="211" x2="530" y2="211" stroke="#b9c6bf"/>'
    for n in [20,25,30,35,40]: inner+=f'<text x="{130+(n-20)/20*400}" y="232" text-anchor="middle" font-size="10">{n}%</text>'
    chart2='<figure class="chart-panel"><h3>Women’s employment: two endpoints</h3>'+svg_chart('Female employment-to-population ratio, ages 15+, 2010 and 2024','Pakistan 21.895% to 22.228%; Bangladesh 34.171% to 37.374%; India 26.238% to 31.090%. Axis begins at 20%.',inner)+'<figcaption>Units: percent of the female population ages 15+. Modelled ILO estimates. Hollow circles: 2010; filled circles: 2024. The axis starts at 20% to make endpoint differences readable. Source: World Bank World Development Indicators. These are employment-to-population ratios, not labour-force participation rates.</figcaption></figure>'
    table='<div class="table-scroll"><table><caption>Supplied endpoint comparisons, 2010–2024</caption><thead><tr><th scope="col">Country</th><th scope="col">Real GDP per capita growth (%)</th><th scope="col">Female employment ratio, 2010 (%)</th><th scope="col">Female employment ratio, 2024 (%)</th><th scope="col">Change (percentage points)</th></tr></thead><tbody>'
    for r in rows: table+=f'<tr><th scope="row">{r["country"]}</th><td>{r["growth"]:.2f}</td><td>{r["employment_2010"]:.3f}</td><td>{r["employment_2024"]:.3f}</td><td>+{r["employment_2024"]-r["employment_2010"]:.3f}</td></tr>'
    return chart1+chart2+table+'</tbody></table></div>'
def case(body):
    return '<div class="wrap case-grid"><aside class="case-index" aria-label="Case study sections"><a href="#overview">Overview</a><a href="#evidence">Evidence & methods</a><a href="#findings">Findings</a><a href="#limitations">Limitations</a><a href="#contribution">Contribution & samples</a></aside><article class="case-content">'+body+'<div class="case-cta"><h3>Have a related analytical question?</h3><p>Let’s discuss the evidence you have and the output you need.</p>'+button('Discuss Your Project',enquiry())+' <a class="text-link" href="/#work">Back to selected work →</a></div></article></div>'
south='''<h2 id="overview">The research question</h2><p>How did economic growth and women’s employment indicators change across three South Asian economies between 2010 and 2024? This descriptive public-data demonstration compares Pakistan, Bangladesh and India to present differences in economic and employment indicators clearly.</p><h2 id="evidence">Data and analytical scope</h2><p>The supplied public-data sample uses two indicators from the World Bank’s World Development Indicators (WDI): GDP per capita in constant 2015 US dollars and the female employment-to-population ratio for women aged 15 and over, based on modelled ILO estimates. The comparison presented here uses observations from 2010 and 2024. The PDF describes an annual dataset containing 45 country-year observations and 135 source values. It reports that all requested values were available and that no imputation or smoothing was applied. These are reported dataset characteristics, not independently verified counts on this website. The comparison is not a population-weighted regional average.</p><p>The analysis is descriptive. It compares percentage changes in real GDP per capita and changes in female employment-to-population ratios between the two years. Changes in employment ratios are expressed in percentage points. No regression models, causal estimates or observations for the intervening years are presented.</p><h2 id="findings">Three economies, different endpoint changes</h2>'''+south_charts()+'''<p>Among the three countries, Bangladesh recorded the largest increase in real GDP per capita (105.72%), followed by India (91.62%) and Pakistan (30.11%). Female employment-to-population ratios increased by 3.203 percentage points in Bangladesh, 4.852 in India and 0.333 in Pakistan. India has the largest employment-ratio increase among the three countries, while Bangladesh has the highest female employment ratio in both 2010 and 2024.</p><h2 id="limitations">What this comparison cannot establish</h2><p>Differences between the two years do not reveal trends within the 2010–2024 period, the drivers of change or a causal relationship between growth and employment. Modelled estimates have methodological limitations. The supplied PDF documents retrieval on 14 October 2026 and a World Bank API database update on 8 October 2026. Raw API responses and the companion dataset were not supplied here, so the website presents verified endpoint summaries and does not reconstruct annual observations.</p><h2 id="contribution">Contribution and available samples</h2><p>This public-data portfolio exercise was prepared for Asif Hussain’s review with AI assistance, as disclosed in the supplied PDF. This is a portfolio demonstration, not a previously published study or a commissioned client assignment. The PDF states that the Python calculations were run and checked. It also states that the accompanying Stata script still requires review and execution in Stata. Those scripts and raw source files are not supplied here; the website does not claim an independent rerun or sole authorship by Asif Hussain.</p><div class="notice"><strong>Source detail and interpretation</strong>WDI indicator codes: NY.GDP.PCAP.KD (GDP per capita); SL.EMP.TOTL.SP.FE.ZS (female employment ratio); SL.EMP.TOTL.SP.MA.ZS (male employment ratio). The PDF reports rounded 2024 male–female gaps of 53.9, 40.2 and 43.2 percentage points for Pakistan, Bangladesh and India. GDP per capita is an average output measure, not median household income, and constant-dollar values are not PPP-adjusted. Changes in the age composition of the population aged 15 and over can affect these ratios.</div>'''+download('south_asia')+'''<p class="small">The PDF mentions a companion ZIP containing raw data and scripts; that archive was not supplied and is not offered as a download.</p>'''
def evidence_table(caption,headers,rows):
    return '<div class="table-scroll"><table><caption>'+e(caption)+'</caption><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+e(value)+('</th>' if i==0 else '</td>') for i,value in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'
h=D['health'];reg=h['regression'];diff=h['bmi_difference']
health='<h2 id="overview">Interpreting supplied statistical outputs</h2><p>This revised sample examines how demographic characteristics relate to BMI, cholesterol and reported heart-attack history. The supplied report contains descriptive statistics, a two-sample t-test, one-way ANOVA, chi-square tests and linear regression. It demonstrates statistical interpretation, technical reporting and communication.</p><div class="notice"><strong>Evidence boundary</strong>This sample is a revision and interpretation based on supplied statistical outputs. The original dataset and analytical script were not available for independent replication.</div><h2 id="evidence">Source, sample and analytical scope</h2><p>The source is the supplied Statistical Analysis Sample PDF, which transcribes Tables 1–14 from statistical_analysis_report.docx. The overall sample contains 1,116 observations; available cases vary across analyses. Original data provenance and collection dates are unspecified. BMI is measured in kg/m²; cholesterol and vitamin C units require verification against a codebook.</p>'
health+=evidence_table('Reported sample characteristics; proportions are not population prevalence estimates',['Measure','Reported result'],h['sample_profile'])
health+='<h2 id="findings">BMI comparison by sex</h2>'
health+=evidence_table('Reported BMI group summaries',['Group','n','Mean BMI (kg/m²)','SD'],[[g['group'],f"{g['n']:,}",f"{g['mean']:.3f}",f"{g['sd']:.3f}"] for g in h['bmi_groups']])
health+=f'<p>The estimated difference in mean BMI (female minus male) is {diff["estimate"]:.3f} BMI units (95% CI {diff["ci_low"]:.3f} to {diff["ci_high"]:.3f}). The reported equal-variance t-test gives t({diff["df"]:,}) = {diff["t"]:.3f}, p = {diff["p"]:.3f}. The test provides insufficient evidence of a difference in mean BMI; it does not establish that the group means are equal.</p><p>The reported standard deviations differ between the two groups. A Welch t-test would be a useful sensitivity check with the original data, but was not run for this revision.</p><h3>Adjusted associations with cholesterol</h3><p>The regression includes age, BMI, vitamin C and sex. Its degrees of freedom imply {reg["complete_cases"]:,} complete cases: F({reg["df_model"]}, {reg["df_residual"]:,}) = {reg["f"]:.2f}, p &lt; 0.001; R² = {reg["r_squared"]:.3f}. The model accounts for 20.1% of observed cholesterol variation within its estimation sample.</p>'
health+=evidence_table('Reported regression; cholesterol units unspecified',['Predictor','Coefficient','95% confidence interval','p value'],[[v['name'],f"{v['coefficient']:.3f}",f"{v['ci_low']:.3f} to {v['ci_high']:.3f}",v['p']] for v in reg['predictors']])
health+='<p>Holding the other included variables constant, each additional year of age is associated with a cholesterol level approximately 1.21 units higher. Each additional BMI unit is associated with a cholesterol level approximately 0.78 units higher. Vitamin C is not statistically significant in this specification. The sex coefficient cannot be interpreted as a female-versus-male difference until the variable’s numeric coding is verified.</p><h3>Additional group comparisons</h3>'
health+=evidence_table('Reported ANOVA and chi-square results',['Comparison','Statistic','p value','Available cases'],h['comparisons'])
health+='<p>The ANOVA results indicate that mean BMI differs across education categories and across self-rated health categories. These omnibus tests do not identify which specific groups differ. A history of heart attack was reported by 46/564 male participants (8.16%) and 16/552 female participants (2.90%). These are unadjusted comparisons within the sample, not estimates of population prevalence. The comparison between rural and urban participants does not provide statistically significant evidence of an association with reported heart-attack history.</p><h2 id="limitations">Coding, representation and replication</h2><p>The sex variable’s numeric coding remains unresolved, so no direction is assigned to its regression coefficient. Sampling design, survey weights, definitions and missing-data handling are insufficiently documented to assess population representativeness. Cholesterol and vitamin C units are unconfirmed.</p><p>The model was not validated on held-out data. Original data and scripts are needed to reproduce results, examine influential observations and residuals, and assess standard-error choices. Findings are statistical associations; they are not causal effects, medical recommendations or population-level prevalence estimates.</p><h2 id="contribution">Revision and available sample</h2><p>The supplied document revises the presentation and interpretation of existing outputs, with AI-assisted language and presentation. It is not an independent rerun. This case study presents the reported statistics alongside their limitations.</p>'+download('health')

r=D['retail']
metrics=[('Number of records',f'{r["records"]:,}'),('Total sales',f'{r["sales"]:,}'),('Total profit',f'{r["profit"]:,}'),('Aggregate profit-to-sales ratio','Approximately 11.62%'),('Mean sales per record','246.51'),('Median sales per record','85.00'),('Mean discount','14.29%'),('Minimum profit per record','−6,599.98'),('Maximum profit per record','8,399.98'),('Reported sales skewness','8.17')]
retail='''<h2 id="overview">A readable business summary</h2><p>This revised business analysis sample presents the supplied retail summary outputs in a concise overview. It examines aggregate sales and profit, the profit-to-sales ratio, and the difference between mean and median sales per record.</p><h2 id="evidence">Source and analytical scope</h2><p>Reported values come from supplied analytical outputs. The supplied Retail Analysis Sample PDF is based on a descriptive-statistics screenshot reproduced in the supplied business reports. The reported period is 2011–2014. The original workbook, data provenance, currency and accounting definitions were not confirmed. This case study interprets descriptive summaries and presents visual comparisons; it does not include a new analysis of the individual records.</p>'''
retail+='<div class="metric-grid">'+''.join(f'<div><strong>{e(v)}</strong><span>{e(k)}</span></div>' for k,v in metrics[:3])+'</div><h2 id="findings">Sales, profit and distribution</h2><div class="table-scroll"><table><caption>Verified summary metrics supplied for the portfolio</caption><thead><tr><th scope="col">Indicator</th><th scope="col">Reported value</th></tr></thead><tbody>'+''.join(f'<tr><th scope="row">{e(k)}</th><td>{e(v)}</td></tr>' for k,v in metrics)+'</tbody></table></div>'
